/**
 * Unit tests for MultivariateNormalDistribution#density
 */
public class MultivariateNormalDistribution_density_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDensityWithCorrectDimension() throws Exception {
        // Setup a 2D Multivariate Normal Distribution
        // Means: [0, 0], Covariance: Identity matrix [[1, 0], [0, 1]]
        double[] means = {0.0, 0.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test point at the mean: [0, 0]
        // Formula: (2*PI)^(-dim/2) * det(Sigma)^(-0.5) * exp(-0.5 * (x-mu)' * Sigma^-1 * (x-mu))
        // dim = 2, det(Sigma) = 1, (x-mu) = [0,0]
        // density = (2*PI)^(-1) * 1 * exp(0) = 1 / (2 * PI)
        double[] vals = {0.0, 0.0};
        double expected = 1.0 / (2.0 * Math.PI);
        double actual = distribution.density(vals);

        assertEquals("Density at mean for identity covariance should match mathematical formula", expected, actual, EPSILON);
    }

    @Test
    public void testDensityWithOffsetAndCovariance() throws Exception {
        // Setup 1D (Special case of Multivariate)
        // Mean: [5.0], Covariance: [[4.0]] (StdDev = 2.0)
        double[] means = {5.0};
        double[][] covariances = {{4.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test point: [7.0]
        // z-score = (7-5)/2 = 1.0
        // Standard Normal density at z=1 is 1/sqrt(2*PI) * exp(-0.5 * 1^2)
        // Multivariate density = (2*PI)^(-1/2) * (4)^(-1/2) * exp(-0.5 * (7-5)^2 / 4)
        // = (2*PI)^(-0.5) * 0.5 * exp(-0.5)
        double[] vals = {7.0};
        double expected = (1.0 / Math.sqrt(2.0 * Math.PI)) * 0.5 * Math.exp(-0.5);
        double actual = distribution.density(vals);

        assertEquals("Density at offset point should match mathematical formula", expected, actual, EPSILON);
    }

    @Test
    public void testDensityThrowsDimensionMismatchException() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Input dimension is 3, but distribution dimension is 2
        double[] invalidVals = {0.0, 0.0, 0.0};

        assertThrows(DimensionMismatchException.class, () -> {
            distribution.density(invalidVals);
        });
    }

    @Test
    public void testDensityWithEmptyDimension() throws Exception {
        // Testing edge case of 0-dimension if allowed by constructor logic
        double[] means = {};
        double[][] covariances = {{}}; // This might throw exception in constructor depending on implementation

        // However, if we assume a valid empty distribution exists:
        // We can't easily construct it due to covariance matrix requirements, 
        // but we can test the dimension check with an empty array if dim is 0.
        // Since we can't force a 0-dim valid covariance easily without internal access, 
        // we rely on the provided dimension mismatch test.
    }
}
